scripts.copy:codemirror:
echo "export { EditorView, basicSetup } from 'codemirror'; export { htmlLanguage, htmlCompletionSource, autoCloseTags } from '@codemirror/lang-html'; export { css } from '@codemirror/lang-css'; export { xml } from '@codemirror/lang-xml'; export { Decoration, MatchDecorator, ViewPlugin, WidgetType, hoverTooltip } from '@codemirror/view'; export { javascript } from '@codemirror/lang-javascript'; export { HighlightStyle, LanguageSupport, syntaxHighlighting, syntaxTree } from '@codemirror/language'; export { tags } from '@lezer/highlight'; export { linter } from '@codemirror/lint'; export { autocompletion } from '@codemirror/autocomplete';" | esbuild --bundle --format=esm --minify --legal-comments=none --banner:js="// SPDX-FileCopyrightText: Marijn Haverbeke and others <https://codemirror.net>
// SPDX-License-Identifier: MIT
" --outfile=public/js/codemirror.js

scripts.copy:tailwind-design:
echo "import { __unstable__loadDesignSystem as load } from 'tailwindcss'; import theme from 'tailwindcss/theme.css'; import utilities from 'tailwindcss/utilities.css'; const sheets = { 'tailwindcss/theme.css': theme, 'tailwindcss/utilities.css': utilities }; export const loadDesignSystem = (css) => load(css, { loadStylesheet: async (id, base) => ({ path: id, base, content: sheets[id] ?? '' }) });" | esbuild --bundle --format=esm --minify --legal-comments=none --loader:.css=text --banner:js="// SPDX-FileCopyrightText: Tailwind Labs, Inc. <https://tailwindcss.com>
// SPDX-License-Identifier: MIT
" --outfile=public/js/tailwindcss-design.js
